def handle(query, state):
    import shlex

    # A tiny in-memory shell executor that operates on state['files'].
    # Supports: cat <path>, ls <dir>, echo <args...>
    # Returns stdout string or an error message.
    def run_cmd(cmd_str, files):
        try:
            tokens = shlex.split(cmd_str.strip())
        except ValueError:
            return ''
        if not tokens:
            return ''
        prog = tokens[0]
        args = tokens[1:]
        if prog == 'cat':
            if not args:
                return 'cat: missing operand'
            path = args[0]
            return files.get(path, 'cat: ' + path + ': No such file or directory')
        elif prog == 'ls':
            prefix = (args[0].rstrip('/') + '/') if args else '/'
            entries = [p[len(prefix):].split('/')[0]
                       for p in files if p.startswith(prefix) and p != prefix]
            seen = []
            for e in entries:
                if e and e not in seen:
                    seen.append(e)
            return '\n'.join(seen) if seen else ''
        elif prog == 'echo':
            return ' '.join(args)
        else:
            return prog + ': command not found'

    # Split a raw shell string on unquoted ; separators.
    # We do NOT use shlex here intentionally — this replicates a naive
    # string-split that creates the injection surface.
    def split_pipeline(raw):
        cmds = []
        current = []
        in_sq = False
        for ch in raw:
            if ch == "'" and not in_sq:
                in_sq = True
                current.append(ch)
            elif ch == "'" and in_sq:
                in_sq = False
                current.append(ch)
            elif ch == ';' and not in_sq:
                cmds.append(''.join(current))
                current = []
            else:
                current.append(ch)
        cmds.append(''.join(current))
        return cmds

    files = state.get('files', {})
    filename = (query.get('filename') or [''])[0]

    if not filename:
        return 200, {'Content-Type': 'text/plain'}, 'Usage: ?filename=<backup_name>'

    # Vulnerable interpolation: user-supplied filename is embedded into a
    # shell command string without sanitisation.
    raw_command = 'cat /backups/' + filename

    # Execute each semicolon-separated command and collect output.
    outputs = []
    for cmd in split_pipeline(raw_command):
        out = run_cmd(cmd, files)
        if out:
            outputs.append(out)

    body = '\n'.join(outputs)
    if not body:
        body = '(empty)'

    return 200, {'Content-Type': 'text/plain'}, body
